--@@HEADER@@
-- GBCore: Game Boy (DMG) CPU (SM83) + memory bus + cartridge MBC + timer + interrupts + PPU.
--
-- Performance design for WoW's Lua 5.1 (interpreted, no JIT):
--  * All machine state is upvalues of closures made by GBCore.New. Every opcode is its
--    own specialised function in ops[] (generated by tools/gen_core.py), so dispatch is
--    one table index + one call, and register access is an upvalue read.
--  * Flags are four booleans; F is only assembled for PUSH AF.
--  * No bitwise ops are needed except 8-bit AND/OR/XOR, which use 64K lookup tables
--    (plain Lua 5.1 has no bit library; tables are ~3 MB, built once per session).
--  * Timer, LY and interrupts are event-driven: the main loop does one
--    `cycles >= nextEvent` compare per instruction. Anything that can raise or unmask an
--    interrupt (IF/IE writes, EI, RETI, HALT, serial) sets nextEvent = cycles to force a check.
--
-- PPU: scanline renderer (each line drawn when mode 3 ends) with fixed mode timings
-- (80/172/204), STAT + LYC interrupts, window line counter, 10-sprite limit, DMG sprite
-- priority. Tiles are decoded into tilePix on VRAM write, so drawing never decodes.
-- Passes dmg-acid2 pixel-for-pixel.
--
-- Joypad: core.SetButton(name, down), with the joypad interrupt on press.
--
-- Game Boy Color mode (ROM header flag 0x80/0xC0): VRAM bank 1 (FF4F), WRAM banks 1-7
-- (FF70, swapped into the flat table on switch), colour palettes (FF68-FF6B), BG tile
-- attributes (palette, bank, flips, priority), CGB sprite priority (OAM order) and
-- master priority (LCDC.0), general-purpose + HBlank DMA (FF51-FF55), double speed
-- (FF4D + STOP). In CGB mode fb holds RGB555 colours (0..0x7FFF) instead of shades.
-- Passes cgb-acid2.
--
-- Battery saves: core.hasBattery, GetSaveRAM() -> hex string, LoadSaveRAM(hex).
--
-- Link cable: with no cable (the default) an internal-clock transfer finishes at once and
-- reads 0xFF. core.SetSerialPort(port) plugs a cable in: port.Master(byte) is called when
-- this Game Boy starts a transfer on its own clock, and the core then stops running
-- (RunFrame returns at once) until core.SerialDone(byteIn) finishes it. port.Slave(byte)
-- is called when the game waits for the other side's clock (SC = 0x80); the host finishes
-- that one with SerialDone too. The callbacks must not run the core.
--
-- Sound: APU registers + channel state (triggers, length, envelope, sweep, 512 Hz frame
-- sequencer) via core.GetAudioState(); the host plays pre-rendered samples. No sample
-- synthesis, and no sub-frame-sequencer quirks (e.g. extra length clocking).
--
-- Not modelled yet: DMG-game colourisation on CGB, variable mode-3 length /
-- mid-line register changes, VRAM/OAM access blocking, sub-instruction memory timing,
-- MBC2, MBC3 RTC, HDMA/GDMA CPU stall time.

GBCore = GBCore or {}

local strbyte, strchar, format = string.byte, string.char, string.format

local CLOCK_HZ = 4194304
local CYCLES_PER_FRAME = 70224
GBCore.CLOCK_HZ = CLOCK_HZ
GBCore.CYCLES_PER_FRAME = CYCLES_PER_FRAME

local TIMER_PERIODS = { [0] = 1024, 16, 64, 256 }

local BATTERY_CARTS = {
    [0x03] = true, [0x06] = true, [0x09] = true, [0x0D] = true, [0x0F] = true,
    [0x10] = true, [0x13] = true, [0x1B] = true, [0x1E] = true,
}

local HEX = {}
for i = 0, 255 do HEX[i] = format("%02x", i) end

-- Sound register read-back: bits that always read as 1 (write-only / unused bits).
local APU_MASK = {
    [0xFF10] = 0x80, [0xFF11] = 0x3F, [0xFF12] = 0x00, [0xFF13] = 0xFF, [0xFF14] = 0xBF,
    [0xFF15] = 0xFF, [0xFF16] = 0x3F, [0xFF17] = 0x00, [0xFF18] = 0xFF, [0xFF19] = 0xBF,
    [0xFF1A] = 0x7F, [0xFF1B] = 0xFF, [0xFF1C] = 0x9F, [0xFF1D] = 0xFF, [0xFF1E] = 0xBF,
    [0xFF1F] = 0xFF, [0xFF20] = 0xFF, [0xFF21] = 0x00, [0xFF22] = 0x00, [0xFF23] = 0xBF,
    [0xFF24] = 0x00, [0xFF25] = 0x00,
}
local APU_BASE = { 0xFF10, 0xFF15, 0xFF1A, 0xFF1F } -- first register of channels 1-4
local WAVE_VOL = { [0] = 0, 15, 8, 4 } -- NR32 output level -> 0..15 equivalent
local floor = math.floor

local MBC_TYPES = {
    [0x00] = "none", [0x08] = "none", [0x09] = "none",
    [0x01] = "mbc1", [0x02] = "mbc1", [0x03] = "mbc1",
    [0x0F] = "mbc3", [0x10] = "mbc3", [0x11] = "mbc3", [0x12] = "mbc3", [0x13] = "mbc3",
    [0x19] = "mbc5", [0x1A] = "mbc5", [0x1B] = "mbc5", [0x1C] = "mbc5", [0x1D] = "mbc5", [0x1E] = "mbc5",
}

------------------------------------------------------------------------------
-- 8-bit logic lookup tables: X8[a * 256 + b] = a OP b
------------------------------------------------------------------------------
local AND8, OR8, XOR8
local function BuildLogicTables()
    if AND8 then return end
    local an, on, xn = {}, {}, {}
    for a = 0, 15 do
        for b = 0, 15 do
            local ra, ro, rx, m, x, y = 0, 0, 0, 1, a, b
            for _ = 0, 3 do
                local xb, yb = x % 2, y % 2
                if xb == 1 and yb == 1 then ra = ra + m end
                if xb == 1 or yb == 1 then ro = ro + m end
                if xb ~= yb then rx = rx + m end
                x, y, m = (x - xb) / 2, (y - yb) / 2, m * 2
            end
            an[a * 16 + b], on[a * 16 + b], xn[a * 16 + b] = ra, ro, rx
        end
    end
    local tA, tO, tX = {}, {}, {}
    for a = 0, 255 do
        local ah, al = (a - a % 16) / 16, a % 16
        for b = 0, 255 do
            local hi, lo = ah * 16 + (b - b % 16) / 16, al * 16 + b % 16
            local k = a * 256 + b
            tA[k] = an[hi] * 16 + an[lo]
            tO[k] = on[hi] * 16 + on[lo]
            tX[k] = xn[hi] * 16 + xn[lo]
        end
    end
    AND8, OR8, XOR8 = tA, tO, tX
end

------------------------------------------------------------------------------
-- GBCore.New(rom) -> core | nil, err      (rom = a GBRomLibrary entry)
------------------------------------------------------------------------------
function GBCore.New(rom)
    BuildLogicTables()
    local AND8, OR8, XOR8 = AND8, OR8, XOR8

    local mbcType = MBC_TYPES[rom.cartType]
    if not mbcType then
        return nil, format("unsupported cartridge type 0x%02X (%s)", rom.cartType, tostring(rom.cartName))
    end

    -- Game Boy Color mode for ROMs that support (0x80) or require (0xC0) it.
    local cgb = rom.cgbFlag == 0x80 or rom.cgbFlag == 0xC0

    -- CPU registers: post-boot-ROM state (A = 0x11 is how software detects a CGB).
    local A, B, C, D, E, H, L = 0x01, 0x00, 0x13, 0x00, 0xD8, 0x01, 0x4D
    local fZ, fN, fH, fC = true, false, true, true
    if cgb then
        A, B, C, D, E, H, L = 0x11, 0x00, 0x00, 0xFF, 0x56, 0x00, 0x0D
        fZ, fN, fH, fC = true, false, false, false
    end
    local SP, PC = 0xFFFE, 0x0100
    local ime, eiStage, halted, locked = false, 0, false, false

    -- Time / events (all in T-cycles, 4.194304 MHz).
    local cycles, nextEvent = 0, 0
    local stopAt, stopOnVBlank = 0, false
    local divBase = -0xABCC -- DIV reads 0xAB right after boot
    local TIMA, TMA, TAC, timerOn, period, nextTimer = 0, 0, 0, false, 1024, 0
    local IE, IF = 0x00, 0x01

    -- Flat 64K table for VRAM/WRAM/OAM/IO/HRAM (keys 0..0xFFFF keep it in the array part).
    local mem = {}
    for a = 0, 0xFFFF do mem[a] = 0 end
    mem[0xFF40], mem[0xFF47], mem[0xFF48], mem[0xFF49] = 0x91, 0xFC, 0xFF, 0xFF
    mem[0xFF41] = 0 -- only the STAT interrupt-enable bits (0x78) are stored here
    mem[0xFF00] = 0x30

    -- PPU state. Modes: 2 = OAM scan (80), 3 = drawing (172), 0 = HBlank (204), 1 = VBlank.
    -- Each line is rendered in one go when mode 3 ends (scanline renderer).
    local HUGE = math.huge
    local LY, ppuMode, nextPPU = 0, 2, 80
    local winLine, winTriggered, statLine = 0, false, false
    -- 160x144 output, 1-based row-major: shades 0..3 (DMG) or RGB555 colours (CGB).
    local fb = {}
    for i = 1, 160 * 144 do fb[i] = cgb and 0x7FFF or 0 end
    -- Decoded tile cache: tilePix[tile * 64 + row * 8 + x] = colour index 0..3. Tiles
    -- 0-383 are VRAM bank 0 (0x8000-0x97FF), 384-767 are CGB bank 1. Kept up to date on
    -- VRAM writes, so drawing never decodes.
    local tilePix = {}
    for i = 0, 768 * 64 - 1 do tilePix[i] = 0 end
    local bgIdx, bgPri, claimed, sprSel = {}, {}, {}, {}
    for x = 0, 159 do bgIdx[x], bgPri[x], claimed[x] = 0, false, false end
    local bgPal, obPal0, obPal1 = { [0] = 0, 1, 2, 3 }, { [0] = 0, 1, 2, 3 }, { [0] = 0, 1, 2, 3 }

    -- CGB state. vram1[a - 0x7FFF] = VRAM bank 1 byte at address a (1-based: array part).
    local vram1 = {}
    for i = 1, 0x2000 do vram1[i] = 0 end
    local vbk = 0
    local bgPalRAM, obPalRAM, bgCol, obCol = {}, {}, {}, {} -- 64 bytes each; col[pal*4+i] = RGB555
    for i = 0, 63 do bgPalRAM[i], obPalRAM[i] = 0xFF, 0xFF end
    for i = 0, 31 do bgCol[i], obCol[i] = 0x7FFF, 0x7FFF end
    local bcps, ocps = 0, 0
    local wramBank, wramStore = 1, {} -- the active bank lives in mem[0xD000..0xDFFF]
    for b = 1, 7 do
        local t = {}
        for i = 0, 4095 do t[i] = 0 end
        wramStore[b] = t
    end
    local key1Prep, doubleSpeed, cpuScale = 0, false, 1 -- cpuScale: real time per CPU cycle
    local hdmaActive, hdmaSrc, hdmaDst, hdmaLen = false, 0, 0, 0

    local function DecodeTileRow(a, bank)
        local off = a - 0x8000
        off = off - off % 2
        local lo, hi
        if bank == 1 then
            lo, hi = vram1[off + 1], vram1[off + 2]
        else
            lo, hi = mem[0x8000 + off], mem[0x8001 + off]
        end
        local base = off * 4 + bank * 24576 -- == tile * 64 + row * 8 (+ 384 tiles for bank 1)
        for x = 7, 0, -1 do
            tilePix[base + x] = (hi % 2) * 2 + lo % 2
            lo, hi = (lo - lo % 2) / 2, (hi - hi % 2) / 2
        end
    end

    local function SetPal(t, v)
        t[0] = v % 4
        v = (v - v % 4) / 4
        t[1] = v % 4
        v = (v - v % 4) / 4
        t[2] = v % 4
        t[3] = (v - v % 4) / 4
    end

    -- STAT interrupt fires on the rising edge of (any enabled condition is true).
    local function StatUpdate()
        local en = mem[0xFF41]
        local line = (LY == mem[0xFF45] and en >= 64)
            or (ppuMode == 0 and en % 16 >= 8)
            or (ppuMode == 1 and en % 32 >= 16)
            or (ppuMode == 2 and en % 64 >= 32)
        if line and not statLine then IF = OR8[IF * 256 + 0x02] end
        statLine = line
    end

    local serial = {}
    local serialPort, serialWait = nil, false -- link cable; true while our own transfer waits

    -- Joypad: pressed-button masks (1 = pressed). D-pad: right 1, left 2, up 4, down 8.
    -- Buttons: a 1, b 2, select 4, start 8. FF00 bits 4/5 (stored in mem) select which
    -- group reads back, active-low.
    local joyDpad, joyBtn = 0, 0

    -- Cartridge.
    local banks, numBanks = rom.banks, rom.numBanks
    local rom0, romN = banks[0], banks[1 % numBanks]
    local ramSize = rom.ramSize or 0
    local extram = {}
    local ramEnabled, ramBank, rtcSelected = false, 0, false
    local bankLo, bankHi, mbc1Mode = 1, 0, 0
    local saveDirty = false

    local rd, wr -- forward declarations

    --------------------------------------------------------------------------
    -- CGB registers FF4D-FF70 (only routed here in CGB mode)
    --------------------------------------------------------------------------
    local function SetWramBank(n)
        n = n % 8
        if n == 0 then n = 1 end
        if n == wramBank then return end
        local cur, nxt = wramStore[wramBank], wramStore[n]
        for i = 0, 4095 do
            cur[i] = mem[0xD000 + i]
            mem[0xD000 + i] = nxt[i]
        end
        wramBank = n
    end

    -- Copy one 16-byte HDMA block from hdmaSrc to VRAM (current bank) at hdmaDst.
    local function HdmaBlock()
        for i = 0, 15 do
            wr(0x8000 + (hdmaDst + i) % 0x2000, rd((hdmaSrc + i) % 65536))
        end
        hdmaSrc = (hdmaSrc + 16) % 65536
        hdmaDst = (hdmaDst + 16) % 0x2000
        hdmaLen = hdmaLen - 1
        if hdmaLen <= 0 then hdmaActive = false end
    end

    -- Palette data write; returns the new spec register (auto-increment if bit 7 set).
    local function PalWrite(ram, col, spec, v)
        local i = spec % 64
        ram[i] = v
        local p = i - i % 2
        col[p / 2] = ram[p] + (ram[p + 1] % 128) * 256
        if spec >= 128 then return 128 + (i + 1) % 64 end
        return spec
    end

    local function CgbRead(a)
        if a == 0xFF4D then return 0x7E + (doubleSpeed and 0x80 or 0) + key1Prep
        elseif a == 0xFF4F then return 0xFE + vbk
        elseif a == 0xFF55 then return hdmaActive and (hdmaLen - 1) or 0xFF
        elseif a == 0xFF68 then return 0x40 + bcps
        elseif a == 0xFF69 then return bgPalRAM[bcps % 64]
        elseif a == 0xFF6A then return 0x40 + ocps
        elseif a == 0xFF6B then return obPalRAM[ocps % 64]
        elseif a == 0xFF70 then return 0xF8 + wramBank
        end
        return mem[a]
    end

    local function CgbWrite(a, v)
        if a == 0xFF4D then key1Prep = v % 2
        elseif a == 0xFF4F then vbk = v % 2
        elseif a == 0xFF55 then
            if hdmaActive and v < 128 then -- writing bit 7 = 0 cancels an HBlank DMA
                hdmaActive = false
                return
            end
            hdmaSrc = mem[0xFF51] * 256 + mem[0xFF52] - mem[0xFF52] % 16
            hdmaDst = (mem[0xFF53] % 32) * 256 + mem[0xFF54] - mem[0xFF54] % 16
            hdmaLen = v % 128 + 1
            if v >= 128 then
                hdmaActive = true -- 16 bytes per HBlank (PPUStep)
            else
                while hdmaLen > 0 do HdmaBlock() end -- general-purpose: all at once
                hdmaActive = false
            end
        elseif a == 0xFF68 then bcps = AND8[v * 256 + 0xBF]
        elseif a == 0xFF69 then bcps = PalWrite(bgPalRAM, bgCol, bcps, v)
        elseif a == 0xFF6A then ocps = AND8[v * 256 + 0xBF]
        elseif a == 0xFF6B then ocps = PalWrite(obPalRAM, obCol, ocps, v)
        elseif a == 0xFF70 then SetWramBank(v)
        else mem[a] = v end
    end

    local function extRead(a)
        if not ramEnabled or rtcSelected or ramSize == 0 then return 0xFF end
        return extram[(ramBank * 0x2000 + a - 0xA000) % ramSize] or 0xFF
    end

    local function extWrite(a, v)
        if not ramEnabled or rtcSelected or ramSize == 0 then return end
        local i = (ramBank * 0x2000 + a - 0xA000) % ramSize
        if extram[i] ~= v then
            extram[i] = v
            saveDirty = true
        end
    end

    local function mbcWrite(a, v)
        if mbcType == "none" then return end
        if a < 0x2000 then
            ramEnabled = (v % 16) == 0x0A
            return
        end
        if mbcType == "mbc1" then
            if a < 0x4000 then bankLo = v % 32
            elseif a < 0x6000 then bankHi = v % 4
            else mbc1Mode = v % 2 end
            local lo = (bankLo == 0) and 1 or bankLo
            romN = banks[(bankHi * 32 + lo) % numBanks]
            if mbc1Mode == 1 then
                rom0, ramBank = banks[(bankHi * 32) % numBanks], bankHi
            else
                rom0, ramBank = banks[0], 0
            end
        elseif mbcType == "mbc3" then
            if a < 0x4000 then
                local b = v % 128
                if b == 0 then b = 1 end
                romN = banks[b % numBanks]
            elseif a < 0x6000 then
                if v < 4 then ramBank, rtcSelected = v, false else rtcSelected = true end
            end -- 0x6000-0x7FFF: RTC latch, not modelled
        else -- mbc5
            if a < 0x3000 then bankLo = v
            elseif a < 0x4000 then bankHi = v % 2
            elseif a < 0x6000 then ramBank = v % 16
            else return end
            romN = banks[(bankHi * 256 + bankLo) % numBanks]
        end
    end

    local function RetimeTimer()
        timerOn = TAC >= 4
        period = TIMER_PERIODS[TAC % 4] * cpuScale -- the timer is clocked by the CPU
        local d = cycles - divBase
        nextTimer = divBase + ((d - d % period) / period + 1) * period
        nextEvent = cycles
    end

    --------------------------------------------------------------------------
    -- APU (sound). Registers, triggers, length counters, envelopes and sweep are
    -- modelled; no audio is synthesised. The host reads channel state once per frame
    -- (core.GetAudioState) and plays pre-rendered samples.
    --------------------------------------------------------------------------
    local apuOn, apuStep, nextAPU = true, 0, 8192 -- frame sequencer: 512 Hz, 8 steps
    local chans = {}
    for c = 1, 4 do
        chans[c] = {
            on = false, dac = false, len = 0, lenEn = false, freq = 0, duty = 2, level = 0,
            vol = 0, envVol = 0, envUp = false, envPace = 0, -- NRx2 as written
            pace = 0, up = false, envTimer = 0,               -- latched on trigger
            trig = 0,                                          -- trigger count
        }
    end
    local swPeriod, swNeg, swShift, swTimer, swEnabled, swShadow = 0, false, 0, 0, false, 0
    local swNegUsed = false -- a negate-mode calculation happened since the last trigger
    local waveWrites = 0    -- bumped on wave RAM writes (GetAudioState caches the hex)
    -- Post-boot state: APU on, master volume max, all channels to both speakers.
    mem[0xFF24], mem[0xFF25], mem[0xFF26] = 0x77, 0xF3, 0xF1
    mem[0xFF11], mem[0xFF12] = 0xBF, 0xF3
    chans[1].dac, chans[1].envVol, chans[1].envPace, chans[1].duty = true, 15, 3, 2

    local function SweepCalc()
        local d = floor(swShadow / 2 ^ swShift)
        if swNeg then
            swNegUsed = true
            return swShadow - d
        end
        return swShadow + d
    end

    -- firstHalf: the next sequencer step won't clock length counters.
    local function ApuTrigger(c, firstHalf)
        local ch = chans[c]
        ch.on = ch.dac
        if ch.len == 0 then
            ch.len = (c == 3) and 256 or 64
            -- Quirk: reloading a zero length while length is enabled in the first half of
            -- a length period loads max - 1.
            if ch.lenEn and firstHalf then ch.len = ch.len - 1 end
        end
        ch.vol, ch.pace, ch.up, ch.envTimer = ch.envVol, ch.envPace, ch.envUp, ch.envPace
        ch.trig = ch.trig + 1
        if c == 1 then
            swNegUsed = false
            swShadow = ch.freq
            swTimer = (swPeriod == 0) and 8 or swPeriod
            swEnabled = swPeriod > 0 or swShift > 0
            if swShift > 0 and SweepCalc() > 2047 then ch.on = false end
        end
    end

    local function ApuSequencerStep()
        local s = apuStep
        apuStep = (s + 1) % 8
        if not apuOn then return end
        if s % 2 == 0 then -- 256 Hz: length counters
            for c = 1, 4 do
                local ch = chans[c]
                if ch.lenEn and ch.len > 0 then
                    ch.len = ch.len - 1
                    if ch.len == 0 then ch.on = false end
                end
            end
        end
        if s == 2 or s == 6 then -- 128 Hz: channel 1 frequency sweep
            if swTimer > 0 then swTimer = swTimer - 1 end
            if swTimer == 0 then
                swTimer = (swPeriod == 0) and 8 or swPeriod
                if swEnabled and swPeriod > 0 then
                    local nf = SweepCalc()
                    if nf > 2047 then
                        chans[1].on = false
                    elseif swShift > 0 then
                        swShadow, chans[1].freq = nf, nf
                        if SweepCalc() > 2047 then chans[1].on = false end
                    end
                end
            end
        end
        if s == 7 then -- 64 Hz: volume envelopes (channels 1, 2, 4)
            for c = 1, 4 do
                local ch = chans[c]
                if c ~= 3 and ch.pace > 0 then
                    ch.envTimer = ch.envTimer - 1
                    if ch.envTimer <= 0 then
                        ch.envTimer = ch.pace
                        if ch.up then
                            if ch.vol < 15 then ch.vol = ch.vol + 1 end
                        elseif ch.vol > 0 then
                            ch.vol = ch.vol - 1
                        end
                    end
                end
            end
        end
    end

    local function ApuRead(a)
        if a >= 0xFF30 then return mem[a] end -- wave RAM
        if a == 0xFF26 then
            local v = 0x70 + (apuOn and 0x80 or 0)
            for c = 1, 4 do
                if chans[c].on then v = v + 2 ^ (c - 1) end
            end
            return v
        end
        local m = APU_MASK[a]
        if not m then return 0xFF end -- FF27-FF2F unused
        return OR8[mem[a] * 256 + m]
    end

    local function ApuWrite(a, v)
        if a >= 0xFF30 then
            mem[a] = v
            waveWrites = waveWrites + 1
            return
        end
        if a == 0xFF26 then
            local on = v >= 128
            if apuOn and not on then -- power off clears every register (lengths survive on DMG)
                for r = 0xFF10, 0xFF25 do mem[r] = 0 end
                for c = 1, 4 do
                    local ch = chans[c]
                    ch.on, ch.dac, ch.lenEn, ch.freq, ch.duty, ch.level = false, false, false, 0, 0, 0
                    ch.envVol, ch.envUp, ch.envPace, ch.vol = 0, false, 0, 0
                    if cgb then ch.len = 0 end
                end
                swPeriod, swNeg, swShift, swEnabled = 0, false, 0, false
            elseif on and not apuOn then
                apuStep = 0
            end
            apuOn = on
            return
        end
        if a > 0xFF25 then return end
        local c = (a >= 0xFF1F) and 4 or (a >= 0xFF1A) and 3 or (a >= 0xFF15) and 2 or 1
        local r = a - APU_BASE[c]
        if not apuOn then
            -- Powered off: only DMG length counters can be written.
            if cgb or r ~= 1 then return end
            local ch = chans[c]
            if c == 3 then ch.len = 256 - v else ch.len = 64 - v % 64 end
            return
        end
        mem[a] = v
        local ch = chans[c]
        if c == 4 and r == 0 then return end -- FF1F unused
        if r == 0 then
            if c == 1 then
                local neg = floor(v / 8) % 2 == 1
                -- Quirk: leaving negate mode after a negate calculation disables channel 1.
                if swNeg and not neg and swNegUsed then ch.on = false end
                swPeriod, swNeg, swShift = floor(v / 16) % 8, neg, v % 8
            elseif c == 3 then
                ch.dac = v >= 128
                if not ch.dac then ch.on = false end
            end
        elseif r == 1 then
            if c == 3 then
                ch.len = 256 - v
            else
                ch.len = 64 - v % 64
                if c ~= 4 then ch.duty = floor(v / 64) end
            end
        elseif r == 2 then
            if c == 3 then
                ch.level = floor(v / 32) % 4
            else
                ch.envVol, ch.envUp, ch.envPace = floor(v / 16), floor(v / 8) % 2 == 1, v % 8
                ch.dac = v >= 8
                if not ch.dac then ch.on = false end
            end
        elseif r == 3 then
            if c ~= 4 then ch.freq = ch.freq - ch.freq % 256 + v end
        else -- r == 4
            if c ~= 4 then ch.freq = (v % 8) * 256 + ch.freq % 256 end
            local wasEn = ch.lenEn
            ch.lenEn = floor(v / 64) % 2 == 1
            local firstHalf = apuStep % 2 == 1
            -- Quirk: enabling length in the first half of a length period clocks it once.
            if firstHalf and ch.lenEn and not wasEn and ch.len > 0 then
                ch.len = ch.len - 1
                if ch.len == 0 and v < 128 then ch.on = false end
            end
            if v >= 128 then ApuTrigger(c, firstHalf) end
        end
    end

    local function ioRead(a)
        if a >= 0xFF10 and a <= 0xFF3F then return ApuRead(a) end
        if cgb and a >= 0xFF4D and a <= 0xFF70 then return CgbRead(a) end
        if a == 0xFF00 then
            local sel = mem[0xFF00]
            local pressed = 0
            if sel % 32 < 16 then pressed = joyDpad end -- bit 4 = 0: d-pad
            if sel < 32 then pressed = OR8[pressed * 256 + joyBtn] end -- bit 5 = 0: buttons
            return 0xC0 + sel + 15 - pressed
        elseif a == 0xFF04 then
            local d = (cycles - divBase) / cpuScale
            d = (d - d % 256) / 256
            return d % 256
        elseif a == 0xFF05 then return TIMA
        elseif a == 0xFF06 then return TMA
        elseif a == 0xFF07 then return 0xF8 + TAC
        elseif a == 0xFF0F then return 0xE0 + IF
        elseif a == 0xFF41 then
            return 0x80 + mem[0xFF41] + ((LY == mem[0xFF45]) and 4 or 0) + ppuMode
        elseif a == 0xFF44 then return LY
        end
        return mem[a]
    end

    local function ioWrite(a, v)
        if a >= 0xFF10 and a <= 0xFF3F then return ApuWrite(a, v) end
        if cgb and a >= 0xFF4D and a <= 0xFF70 then return CgbWrite(a, v) end
        if a == 0xFF00 then
            mem[a] = AND8[v * 256 + 0x30]
        elseif a == 0xFF02 then
            mem[a] = v
            if v >= 0x80 and v % 2 == 1 then
                if serialPort then
                    -- Our clock, cable plugged in: stop until the other Game Boy's byte arrives.
                    serialWait = true
                    stopAt = cycles
                    serialPort.Master(mem[0xFF01])
                else
                    -- Internal-clock transfer with nothing attached: completes "instantly".
                    serial[#serial + 1] = strchar(mem[0xFF01])
                    mem[0xFF01] = 0xFF
                    mem[0xFF02] = v - 0x80
                    IF = OR8[IF * 256 + 0x08]
                    nextEvent = cycles
                end
            elseif v >= 0x80 and serialPort then
                serialPort.Slave(mem[0xFF01]) -- waiting for the other side's clock
            end
        elseif a == 0xFF04 then
            divBase = cycles
            RetimeTimer()
        elseif a == 0xFF05 then TIMA = v
        elseif a == 0xFF06 then TMA = v
        elseif a == 0xFF07 then
            TAC = v % 8
            RetimeTimer()
        elseif a == 0xFF0F then
            IF = v % 32
            nextEvent = cycles
        elseif a == 0xFF40 then
            local was = mem[0xFF40] >= 128
            mem[0xFF40] = v
            if was and v < 128 then -- LCD off: LY=0, mode 0, PPU stops
                LY, ppuMode, nextPPU, statLine = 0, 0, HUGE, false
            elseif v >= 128 and not was then -- LCD on: restart at line 0
                LY, ppuMode, nextPPU, winLine = 0, 2, cycles + 80, 0
                winTriggered = mem[0xFF4A] == 0
                StatUpdate()
            end
            nextEvent = cycles
        elseif a == 0xFF41 then
            mem[a] = AND8[v * 256 + 0x78]
            if mem[0xFF40] >= 128 then StatUpdate() end
            nextEvent = cycles
        elseif a == 0xFF45 then
            mem[a] = v
            if mem[0xFF40] >= 128 then StatUpdate() end
            nextEvent = cycles
        elseif a == 0xFF47 then mem[a] = v; SetPal(bgPal, v)
        elseif a == 0xFF48 then mem[a] = v; SetPal(obPal0, v)
        elseif a == 0xFF49 then mem[a] = v; SetPal(obPal1, v)
        elseif a == 0xFF44 then
            -- LY is read-only
        elseif a == 0xFF46 then
            mem[a] = v
            local src = v * 256
            for i = 0, 159 do mem[0xFE00 + i] = rd(src + i) end
        else
            mem[a] = v
        end
    end

    rd = function(a)
        if a < 0x4000 then return strbyte(rom0, a + 1) end
        if a < 0x8000 then return strbyte(romN, a - 0x3FFF) end
        if a < 0xA000 then -- VRAM
            if vbk == 1 then return vram1[a - 0x7FFF] end
            return mem[a]
        end
        if a >= 0xFF00 then
            if a >= 0xFF80 then
                if a == 0xFFFF then return IE end
                return mem[a]
            end
            return ioRead(a)
        end
        if a >= 0xA000 then
            if a < 0xC000 then return extRead(a) end
            if a >= 0xE000 and a < 0xFE00 then a = a - 0x2000 end -- echo RAM
        end
        return mem[a]
    end

    wr = function(a, v)
        if a < 0x8000 then return mbcWrite(a, v) end
        if a < 0xA000 then -- VRAM
            if vbk == 1 then
                vram1[a - 0x7FFF] = v
                if a < 0x9800 then DecodeTileRow(a, 1) end
            else
                mem[a] = v
                if a < 0x9800 then DecodeTileRow(a, 0) end
            end
            return
        end
        if a >= 0xFF00 then
            if a >= 0xFF80 then
                if a == 0xFFFF then
                    IE = v
                    nextEvent = cycles
                else
                    mem[a] = v
                end
                return
            end
            return ioWrite(a, v)
        end
        if a >= 0xA000 then
            if a < 0xC000 then return extWrite(a, v) end
            if a >= 0xFEA0 then return end -- unusable region
            if a >= 0xE000 and a < 0xFE00 then a = a - 0x2000 end
        end
        mem[a] = v
    end

    local function imm8()
        local pc = PC
        PC = (pc + 1) % 65536
        if pc < 0x4000 then return strbyte(rom0, pc + 1) end
        return rd(pc)
    end

    local function imm16()
        local lo = imm8()
        return imm8() * 256 + lo
    end

    local function push16(v)
        SP = (SP + 65535) % 65536
        wr(SP, (v - v % 256) / 256)
        SP = (SP + 65535) % 65536
        wr(SP, v % 256)
    end

    local function pop16()
        local lo = rd(SP)
        SP = (SP + 1) % 65536
        local hi = rd(SP)
        SP = (SP + 1) % 65536
        return hi * 256 + lo
    end

    --------------------------------------------------------------------------
    -- ALU helpers (operate on A / flags)
    --------------------------------------------------------------------------
    local function add8(v, c)
        local r = A + v + c
        fH = (A % 16) + (v % 16) + c > 15
        fC = r > 255
        r = r % 256
        A, fZ, fN = r, r == 0, false
    end

    local function sub8(v, c)
        local r = A - v - c
        fH = (A % 16) - (v % 16) - c < 0
        fC = r < 0
        r = r % 256
        A, fZ, fN = r, r == 0, true
    end

    local function cp8(v)
        local r = A - v
        fH = (A % 16) < (v % 16)
        fC, fZ, fN = r < 0, r == 0, true
    end

    local function inc8(v)
        local r = (v + 1) % 256
        fZ, fN, fH = r == 0, false, v % 16 == 15
        return r
    end

    local function dec8(v)
        local r = (v + 255) % 256
        fZ, fN, fH = r == 0, true, v % 16 == 0
        return r
    end

    local function addhl(v)
        local hl = H * 256 + L
        local r = hl + v
        fN = false
        fH = (hl % 4096) + (v % 4096) > 4095
        fC = r > 65535
        r = r % 65536
        H, L = (r - r % 256) / 256, r % 256
    end

    local function daa()
        local a = A
        if not fN then
            if fC or a > 0x99 then a = a + 0x60; fC = true end
            if fH or a % 16 > 9 then a = a + 0x06 end
        else
            if fC then a = a - 0x60 end
            if fH then a = a - 0x06 end
        end
        a = a % 256
        A, fZ, fH = a, a == 0, false
    end

    -- Rotates/shifts: return the result, set all four flags.
    local function rlc(v)
        local c = v >= 128
        local r = (v * 2) % 256 + (c and 1 or 0)
        fZ, fN, fH, fC = r == 0, false, false, c
        return r
    end
    local function rrc(v)
        local c = v % 2 == 1
        local r = (v - v % 2) / 2 + (c and 128 or 0)
        fZ, fN, fH, fC = r == 0, false, false, c
        return r
    end
    local function rl(v)
        local r = (v * 2) % 256 + (fC and 1 or 0)
        fZ, fN, fH, fC = r == 0, false, false, v >= 128
        return r
    end
    local function rr(v)
        local r = (v - v % 2) / 2 + (fC and 128 or 0)
        fZ, fN, fH, fC = r == 0, false, false, v % 2 == 1
        return r
    end
    local function sla(v)
        local r = (v * 2) % 256
        fZ, fN, fH, fC = r == 0, false, false, v >= 128
        return r
    end
    local function sra(v)
        local r = (v - v % 2) / 2 + (v >= 128 and 128 or 0)
        fZ, fN, fH, fC = r == 0, false, false, v % 2 == 1
        return r
    end
    local function swap(v)
        local r = (v % 16) * 16 + (v - v % 16) / 16
        fZ, fN, fH, fC = r == 0, false, false, false
        return r
    end
    local function srl(v)
        local r = (v - v % 2) / 2
        fZ, fN, fH, fC = r == 0, false, false, v % 2 == 1
        return r
    end

    -- STOP: on CGB with KEY1 bit 0 armed, toggles double speed (and resets DIV).
    local function stop()
        if cgb and key1Prep == 1 then
            key1Prep = 0
            doubleSpeed = not doubleSpeed
            cpuScale = doubleSpeed and 0.5 or 1
            divBase = cycles
            RetimeTimer()
        end
    end

    --------------------------------------------------------------------------
    -- Opcodes (generated)
    --------------------------------------------------------------------------
    local ops, cb = {}, {}
--@@OPS@@

    --------------------------------------------------------------------------
    -- Scanline renderer (DMG): background, window, sprites -> fb row LY.
    --------------------------------------------------------------------------
    -- Draw BG/window pixels x..xEnd-1 of one line, one tile span at a time.
    -- px = x position within the 256-wide tile map for the first pixel.
    local function DrawTiles(row, mapRow, fineY, x, xEnd, px, unsignedTiles, pal)
        while x < xEnd do
            local fx = px % 8
            local t = mem[mapRow + (px - fx) / 8]
            if t < 128 and not unsignedTiles then t = t + 256 end
            local src = t * 64 + fineY + fx
            local n = 8 - fx
            if x + n > xEnd then n = xEnd - x end
            local o = row + x
            for i = 0, n - 1 do
                local c = tilePix[src + i]
                bgIdx[x + i] = c
                fb[o + i] = pal[c]
            end
            x = x + n
            px = (px + n) % 256
        end
    end

    local function RenderLine(ly)
        local lcdc = mem[0xFF40]
        local row = ly * 160 + 1
        local pal = bgPal

        if lcdc % 2 == 1 then
            local unsignedTiles = lcdc % 32 >= 16
            -- Window: shown from x = WX-7 once LY has matched WY this frame.
            local winX, wx0 = 160, 0
            if winTriggered and lcdc % 64 >= 32 then
                wx0 = mem[0xFF4B] - 7
                if wx0 < 160 then winX = (wx0 < 0) and 0 or wx0 end
            end

            if winX > 0 then
                local map = (lcdc % 16 >= 8) and 0x9C00 or 0x9800
                local y = (ly + mem[0xFF42]) % 256
                DrawTiles(row, map + (y - y % 8) * 4, (y % 8) * 8, 0, winX, mem[0xFF43], unsignedTiles, pal)
            end

            if winX < 160 then
                local map = (lcdc % 128 >= 64) and 0x9C00 or 0x9800
                local wy = winLine
                DrawTiles(row, map + (wy - wy % 8) * 4, (wy % 8) * 8, winX, 160, winX - wx0, unsignedTiles, pal)
                winLine = winLine + 1
            end
        else
            -- LCDC.0 off on DMG: background and window are blank (white).
            for x = 0, 159 do
                bgIdx[x] = 0
                fb[row + x] = 0
            end
        end

        if lcdc % 4 >= 2 then
            -- OAM scan: first 10 sprites (in OAM order) overlapping this line.
            local h = (lcdc % 8 >= 4) and 16 or 8
            local n = 0
            for s = 0xFE00, 0xFE9C, 4 do
                local sy = mem[s] - 16
                if ly >= sy and ly < sy + h then
                    n = n + 1
                    sprSel[n] = s
                    if n == 10 then break end
                end
            end
            if n > 0 then
                -- DMG priority: lower X first, ties by OAM order (stable insertion sort).
                for i = 2, n do
                    local s = sprSel[i]
                    local sx = mem[s + 1]
                    local j = i - 1
                    while j >= 1 and mem[sprSel[j] + 1] > sx do
                        sprSel[j + 1] = sprSel[j]
                        j = j - 1
                    end
                    sprSel[j + 1] = s
                end
                for x = 0, 159 do claimed[x] = false end
                -- Highest-priority opaque pixel claims x, even if BG then hides it.
                for i = 1, n do
                    local s = sprSel[i]
                    local sx, tile, attr = mem[s + 1] - 8, mem[s + 2], mem[s + 3]
                    local line = ly - (mem[s] - 16)
                    if attr % 128 >= 64 then line = h - 1 - line end
                    if h == 16 then
                        tile = tile - tile % 2
                        if line >= 8 then tile, line = tile + 1, line - 8 end
                    end
                    local xflip = attr % 64 >= 32
                    local behind = attr >= 128
                    local opal = (attr % 32 >= 16) and obPal1 or obPal0
                    local base = tile * 64 + line * 8
                    for i2 = 0, 7 do
                        local x = sx + i2
                        if x >= 0 and x < 160 and not claimed[x] then
                            local c = tilePix[base + (xflip and (7 - i2) or i2)]
                            if c ~= 0 then
                                claimed[x] = true
                                if not (behind and bgIdx[x] ~= 0) then fb[row + x] = opal[c] end
                            end
                        end
                    end
                end
            end
        end
    end

    --------------------------------------------------------------------------
    -- Scanline renderer (CGB): per-tile attributes from VRAM bank 1, colour palettes.
    --------------------------------------------------------------------------
    -- y = line within the 256-line map (BG) or the window line counter.
    local function DrawTilesCGB(row, map, y, x, xEnd, px, unsignedTiles)
        local mapRow = map + (y - y % 8) * 4
        local fy = y % 8
        while x < xEnd do
            local fx = px % 8
            local ma = mapRow + (px - fx) / 8
            local t = mem[ma]
            local attr = vram1[ma - 0x7FFF]
            if t < 128 and not unsignedTiles then t = t + 256 end
            if attr % 16 >= 8 then t = t + 384 end -- tile data from VRAM bank 1
            local src = t * 64 + ((attr % 128 >= 64) and (7 - fy) or fy) * 8
            local palBase = (attr % 8) * 4
            local pri = attr >= 128
            local n = 8 - fx
            if x + n > xEnd then n = xEnd - x end
            local o = row + x
            if attr % 64 >= 32 then -- x flip
                src = src + 7 - fx
                for i = 0, n - 1 do
                    local c = tilePix[src - i]
                    bgIdx[x + i], bgPri[x + i] = c, pri
                    fb[o + i] = bgCol[palBase + c]
                end
            else
                src = src + fx
                for i = 0, n - 1 do
                    local c = tilePix[src + i]
                    bgIdx[x + i], bgPri[x + i] = c, pri
                    fb[o + i] = bgCol[palBase + c]
                end
            end
            x = x + n
            px = (px + n) % 256
        end
    end

    local function RenderLineCGB(ly)
        local lcdc = mem[0xFF40]
        local row = ly * 160 + 1
        local unsignedTiles = lcdc % 32 >= 16

        local winX, wx0 = 160, 0
        if winTriggered and lcdc % 64 >= 32 then
            wx0 = mem[0xFF4B] - 7
            if wx0 < 160 then winX = (wx0 < 0) and 0 or wx0 end
        end
        if winX > 0 then
            local map = (lcdc % 16 >= 8) and 0x9C00 or 0x9800
            DrawTilesCGB(row, map, (ly + mem[0xFF42]) % 256, 0, winX, mem[0xFF43], unsignedTiles)
        end
        if winX < 160 then
            local map = (lcdc % 128 >= 64) and 0x9C00 or 0x9800
            DrawTilesCGB(row, map, winLine, winX, 160, winX - wx0, unsignedTiles)
            winLine = winLine + 1
        end

        -- On CGB, LCDC.0 is "master priority": when clear, sprites are always on top.
        local masterPri = lcdc % 2 == 1
        if lcdc % 4 >= 2 then
            local h = (lcdc % 8 >= 4) and 16 or 8
            local n = 0
            for s = 0xFE00, 0xFE9C, 4 do
                local sy = mem[s] - 16
                if ly >= sy and ly < sy + h then
                    n = n + 1
                    sprSel[n] = s
                    if n == 10 then break end
                end
            end
            if n > 0 then
                for x = 0, 159 do claimed[x] = false end
                -- CGB priority is OAM order only (no X sort).
                for i = 1, n do
                    local s = sprSel[i]
                    local sx, tile, attr = mem[s + 1] - 8, mem[s + 2], mem[s + 3]
                    local line = ly - (mem[s] - 16)
                    if attr % 128 >= 64 then line = h - 1 - line end
                    if h == 16 then
                        tile = tile - tile % 2
                        if line >= 8 then tile, line = tile + 1, line - 8 end
                    end
                    if attr % 16 >= 8 then tile = tile + 384 end
                    local xflip = attr % 64 >= 32
                    local behind = attr >= 128
                    local palBase = (attr % 8) * 4
                    local base = tile * 64 + line * 8
                    for i2 = 0, 7 do
                        local x = sx + i2
                        if x >= 0 and x < 160 and not claimed[x] then
                            local c = tilePix[base + (xflip and (7 - i2) or i2)]
                            if c ~= 0 then
                                claimed[x] = true
                                if not masterPri or bgIdx[x] == 0 or not (behind or bgPri[x]) then
                                    fb[row + x] = obCol[palBase + c]
                                end
                            end
                        end
                    end
                end
            end
        end
    end

    local renderLine = cgb and RenderLineCGB or RenderLine

    -- Advance the PPU one mode transition.
    local function PPUStep()
        if ppuMode == 2 then
            ppuMode = 3
            nextPPU = nextPPU + 172
            return -- no STAT source for mode 3
        elseif ppuMode == 3 then
            renderLine(LY)
            ppuMode = 0
            nextPPU = nextPPU + 204
            if hdmaActive then HdmaBlock() end -- HBlank DMA: 16 bytes per line
        elseif ppuMode == 0 then
            LY = LY + 1
            if LY == 144 then
                ppuMode = 1
                nextPPU = nextPPU + 456
                IF = OR8[IF * 256 + 0x01]
                if stopOnVBlank then stopAt = cycles end
            else
                ppuMode = 2
                nextPPU = nextPPU + 80
                if LY == mem[0xFF4A] then winTriggered = true end
            end
        else -- VBlank lines 144..153
            LY = LY + 1
            if LY == 154 then
                LY, ppuMode, winLine = 0, 2, 0
                nextPPU = nextPPU + 80
                winTriggered = mem[0xFF4A] == 0
            else
                nextPPU = nextPPU + 456
            end
        end
        StatUpdate()
    end

    --------------------------------------------------------------------------
    -- Events: PPU, timer, EI delay, interrupt dispatch. Recomputes nextEvent.
    --------------------------------------------------------------------------
    local function Events()
        while cycles >= nextPPU do PPUStep() end
        while cycles >= nextAPU do
            ApuSequencerStep()
            nextAPU = nextAPU + 8192
        end
        if timerOn then
            while cycles >= nextTimer do
                TIMA = TIMA + 1
                if TIMA > 255 then
                    TIMA = TMA
                    IF = OR8[IF * 256 + 0x04]
                end
                nextTimer = nextTimer + period
            end
        end

        if eiStage == 1 then
            eiStage = 2 -- EI takes effect after the *next* instruction
        elseif eiStage == 2 then
            eiStage, ime = 0, true
        end

        local pending = AND8[IE * 256 + IF] % 32
        if pending ~= 0 then
            if not locked then halted = false end
            if ime then
                local bitv, vec = 1, 0x40
                while pending % 2 == 0 do
                    pending, bitv, vec = pending / 2, bitv * 2, vec + 8
                end
                IF = IF - bitv
                ime = false
                push16(PC)
                PC = vec
                cycles = cycles + 20 * cpuScale
            end
        end

        nextEvent = nextPPU
        if nextAPU < nextEvent then nextEvent = nextAPU end
        if timerOn and nextTimer < nextEvent then nextEvent = nextTimer end
        if eiStage ~= 0 then nextEvent = cycles end
    end

    --------------------------------------------------------------------------
    -- Public API
    --------------------------------------------------------------------------
    local core = {
        rom = rom, mbc = mbcType, cgb = cgb,
        hasBattery = BATTERY_CARTS[rom.cartType] == true and ramSize > 0,
    }

    local function Run()
        if serialWait then return end
        local ops = ops
        while cycles < stopAt do
            if halted then
                if nextEvent > cycles then
                    cycles = (nextEvent < stopAt) and nextEvent or stopAt
                end
                Events()
            else
                local pc = PC
                local op
                if pc < 0x4000 then
                    op = strbyte(rom0, pc + 1)
                elseif pc < 0x8000 then
                    op = strbyte(romN, pc - 0x3FFF)
                else
                    op = rd(pc)
                end
                PC = (pc + 1) % 65536
                cycles = cycles + ops[op]() * cpuScale -- 0.5 in CGB double speed
                if cycles >= nextEvent then Events() end
            end
        end
    end

    -- Runs at least n T-cycles (may overshoot by one instruction).
    function core.RunCycles(n)
        stopOnVBlank, stopAt = false, cycles + n
        Run()
    end

    -- Runs until the next VBlank starts (fb then holds a complete frame), or for one
    -- frame's worth of cycles if the LCD is off.
    function core.RunFrame()
        stopOnVBlank, stopAt = true, cycles + CYCLES_PER_FRAME
        Run()
        stopOnVBlank = false
    end

    function core.GetCycles() return cycles end

    -- name: "right" "left" "up" "down" "a" "b" "select" "start"; down: true = pressed.
    -- A press raises the joypad interrupt (IF bit 4), which also wakes HALT.
    local BUTTONS = {
        right = { false, 1 }, left = { false, 2 }, up = { false, 4 }, down = { false, 8 },
        a = { true, 1 }, b = { true, 2 }, select = { true, 4 }, start = { true, 8 },
    }
    function core.SetButton(name, down)
        local b = BUTTONS[name]
        if not b then return end
        local m = b[2]
        local mask = b[1] and joyBtn or joyDpad
        local was = AND8[mask * 256 + m] ~= 0
        if down and not was then
            mask = mask + m
            IF = OR8[IF * 256 + 0x10]
            nextEvent = cycles
        elseif was and not down then
            mask = mask - m
        else
            return
        end
        if b[1] then joyBtn = mask else joyDpad = mask end
    end

    function core.ReleaseAllButtons() joyDpad, joyBtn = 0, 0 end

    -- Serial output since start (Blargg tests print their results here).
    function core.GetSerial() return table.concat(serial) end

    -- Link cable (see the header). SerialState() -> "master" (our transfer is waiting),
    -- "slave" (armed, waiting for the other side's clock) or nil, plus the byte in SB.
    function core.SerialState()
        local sc = mem[0xFF02]
        if serialWait then return "master", mem[0xFF01] end
        if sc >= 0x80 and sc % 2 == 0 then return "slave", mem[0xFF01] end
        return nil, mem[0xFF01]
    end

    -- Finishes the transfer in progress: SB = byteIn, SC bit 7 cleared, serial interrupt.
    function core.SerialDone(byteIn)
        if mem[0xFF02] < 0x80 then serialWait = false return false end
        mem[0xFF01] = byteIn % 256
        mem[0xFF02] = mem[0xFF02] - 0x80
        IF = OR8[IF * 256 + 0x08]
        nextEvent = cycles
        serialWait = false
        return true
    end

    -- Plugs a cable in (port table) or pulls it out (nil). Pulling it out mid-transfer
    -- finishes the transfer with 0xFF, as on hardware with nothing on the other end.
    function core.SetSerialPort(port)
        serialPort = port
        if not port and serialWait then core.SerialDone(0xFF) end
    end

    function core.IsLocked() return locked end

    function core.GetRegs()
        return {
            A = A, B = B, C = C, D = D, E = E, H = H, L = L, SP = SP, PC = PC,
            F = (fZ and 0x80 or 0) + (fN and 0x40 or 0) + (fH and 0x20 or 0) + (fC and 0x10 or 0),
            ime = ime, halted = halted, locked = locked, cycles = cycles,
        }
    end

    -- Cartridge RAM as a hex string (2 chars per byte; safe in SavedVariables).
    function core.GetSaveRAM()
        local parts = {}
        for i = 0, ramSize - 1 do parts[i + 1] = HEX[extram[i] or 0xFF] end
        return table.concat(parts)
    end

    function core.LoadSaveRAM(s)
        if type(s) ~= "string" or #s ~= ramSize * 2 or s:find("[^%x]") then return false end
        for i = 0, ramSize - 1 do
            extram[i] = tonumber(s:sub(i * 2 + 1, i * 2 + 2), 16)
        end
        saveDirty = false
        return true
    end

    function core.IsSaveDirty() return saveDirty end
    function core.ClearSaveDirty() saveDirty = false end
    function core.IsDoubleSpeed() return doubleSpeed end

    -- Sound channel state for the host's sample player (one reused table; read, don't keep).
    -- [c] = { on, freq (11-bit register value), duty (0-3), vol (0-15), trig (trigger
    -- count), left, right }; [3].wave = wave RAM as hex; [4].nr43 = noise settings.
    -- pace/up = the envelope latched at the last trigger (pace 0 = constant volume).
    local audioState = { {}, {}, {}, {} }
    local waveHex, waveHexAt = "", -1
    function core.GetAudioState()
        local nr51 = mem[0xFF25]
        for c = 1, 4 do
            local ch, o = chans[c], audioState[c]
            o.on = apuOn and ch.on and ch.dac
            o.freq, o.duty, o.vol, o.trig = ch.freq, ch.duty, ch.vol, ch.trig
            o.pace, o.up = ch.pace, ch.up
            o.left = floor(nr51 / 2 ^ (c + 3)) % 2 == 1
            o.right = floor(nr51 / 2 ^ (c - 1)) % 2 == 1
        end
        audioState[3].vol = WAVE_VOL[chans[3].level]
        if waveHexAt ~= waveWrites then -- rebuild only after wave RAM writes
            local w = {}
            for i = 0, 15 do w[i + 1] = HEX[mem[0xFF30 + i]] end
            waveHex, waveHexAt = table.concat(w), waveWrites
        end
        audioState[3].wave = waveHex
        audioState[4].nr43 = mem[0xFF22]
        return audioState
    end

    -- Cartridge RAM byte i (0-based), regardless of the RAM-enable latch (tests/debugging).
    function core.ReadCartRAM(i) return extram[i] or 0xFF end

    -- Read VRAM bank 0/1 directly (tests/debugging), independent of FF4F.
    function core.ReadVRAM(bank, a)
        if bank == 1 then return vram1[a - 0x7FFF] end
        return mem[a]
    end

    core.Read, core.Write = rd, wr
    core.mem = mem
    core.fb = fb
    return core
end
